<?php defined( 'ABSPATH' ) || exit; get_header(); $page_id = (int) get_option( 'page_for_posts' ); ?>
<header class="page-heading container"><p class="eyebrow">ARTICLES / INSIGHTS</p><h1><?php echo esc_html( $page_id ? get_the_title( $page_id ) : __( 'Notes from the work.', 'sidartha' ) ); ?></h1><div class="page-intro prose"><?php if ( $page_id ) { echo apply_filters( 'the_content', get_post_field( 'post_content', $page_id ) ); } // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></div></header>
<section class="container section-bottom"><div class="articles-grid"><?php while ( have_posts() ) : the_post(); skp_article_card( 'h2' ); endwhile; if ( ! have_posts() && 0 === $wp_query->post_count ) : ?><div class="empty-state"><h2>The notebook is open.</h2><p>New articles will appear here when they’re ready.</p></div><?php endif; ?></div><?php the_posts_pagination( array( 'mid_size' => 1, 'prev_text' => '← Previous', 'next_text' => 'Next →' ) ); ?></section>
<?php skp_contact_band(); get_footer(); ?>
